│                                    │                                        │
│              ┌─────────────────────┼─────────────────────┐                 │
│              │                     │                     │                 │
│    ┌─────────┴─────────┐ ┌────────┴────────┐ ┌─────────┴─────────┐        │
│    │ ConcreteStrategyA │ │ConcreteStrategyB│ │ ConcreteStrategyC │        │
│    ├───────────────────┤ ├─────────────────┤ ├───────────────────┤        │
│    │                   │ │                 │ │                   │        │
│    ├───────────────────┤ ├─────────────────┤ ├───────────────────┤        │
│    │ + execute(data)   │ │ + execute(data) │ │ + execute(data)   │        │
│    │   // Algorithm A  │ │   // Algorithm B│ │   // Algorithm C  │        │
│    └───────────────────┘ └─────────────────┘ └───────────────────┘        │
│                                                                             │
